<script lang="ts">
 import {kilowatts,kilowattsLabel,wattsFromKilowatts} from '$lib/utils/powerUnits';
 import type { FlowGraph, FlowMetric, FlowNode, FlowSelection, FlowState } from '$lib/power-flow/types';
 import {patchOutputPorts} from '$lib/power-flow/editorModel';
 import {deriveLoadDisplay,remainingCapacity,type LoadDisplayMode} from '$lib/power-flow/loadDisplay';
 let {graph,state,selection,editable,onchange,ondelete,onclose,peaksLoading=false,peaksError='',onretrypeaks=()=>{},displayMode='current'}:{graph:FlowGraph;state:FlowState|null;displayMode?:LoadDisplayMode;selection:FlowSelection|null;editable:boolean;onchange:(graph:FlowGraph)=>void;ondelete:()=>void;onclose:()=>void;peaksLoading?:boolean;peaksError?:string;onretrypeaks?:()=>void}=$props();
 const node=$derived(selection?.kind==='node'?graph.nodes.find(n=>n.id===selection.id):undefined);
 const edge=$derived(selection?.kind==='edge'?graph.edges.find(e=>e.id===selection.id):undefined);
 const metric=$derived(selection?(selection.kind==='node'?state?.nodes[selection.id]:state?.edges[selection.id]):undefined);
 const peakState=$derived(displayMode==='peak'?deriveLoadDisplay(state,graph,'peak'):null);
 const peakMetric=$derived(selection?(selection.kind==='node'?peakState?.nodes[selection.id]:peakState?.edges[selection.id]):undefined);
 const remaining=$derived(remainingCapacity(peakMetric));
 const names={breaker:'차단기',outlet:'콘센트',strip:'멀티탭',server:'서버',psu:'PSU',fixed:'고정 부하'};
 function number(event:Event):number|null {const raw=(event.target as HTMLInputElement).value;return raw===''?null:Number(raw);}
 function patchNode(patch:Partial<FlowNode>){if(node)onchange({...graph,nodes:graph.nodes.map(n=>n.id===node.id?{...n,...patch}:n)});}
 function patchEdge(patch:Record<string,unknown>){if(edge)onchange({...graph,edges:graph.edges.map(e=>e.id===edge.id?{...e,...patch}:e)});}
 function setting(key:'voltage_v'|'power_factor'|'max_age_seconds'|'max_skew_seconds',event:Event){const value=number(event);if(value!==null)onchange({...graph,settings:{...graph.settings,[key]:value}});}
 function format(value:number|null|undefined,unit:string){return unit==='kW'?kilowattsLabel(value):value==null?'—':`${value.toLocaleString('ko-KR',{maximumFractionDigits:unit==='A'?2:1})} ${unit}`;}
 function current(m:FlowMetric|undefined,kind:'watts'|'amps'){if(!m)return '—';const value=m[kind];const known=kind==='watts'?m.known_watts:m.known_amps;const amount=value??(known>0?known:null);if(amount===null)return '—';return `${!m.complete&&known>0?'≥ ':''}${kind==='amps'&&m.amps_estimated?'≈ ':''}${format(amount,kind==='watts'?'kW':'A')}`;}
 function time(value:string|null|undefined){return value?new Date(value).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';}
 const voltage=$derived(metric?.voltage_v??node?.voltage_v??graph.settings.voltage_v);
 const pf=$derived(metric?.power_factor??node?.power_factor??graph.settings.power_factor);
 const capacity=$derived(node?.capacity_a??edge?.capacity_a??null);
</script>
<aside class="pf-properties" aria-label="선택 항목 속성">
 <div class="pf-panel-title"><h2>{node?names[node.kind]:edge?'케이블':'도면 설정'}</h2><button class="pf-panel-close" onclick={onclose} aria-label="속성 패널 닫기">×</button></div>
 {#if node||edge}
 <label class="pf-field">이름<input disabled={!editable} value={node?.label??edge?.label??''} onchange={event=>node?patchNode({label:event.currentTarget.value}):patchEdge({label:event.currentTarget.value})}/></label>
 {#if node?.kind==='server'}<label class="pf-field">Rack<input maxlength="64" disabled={!editable} value={node.rack??''} onchange={event=>patchNode({rack:event.currentTarget.value.trim()||null})}/></label>{/if}
 {#if node?.kind==='psu'}<p class="pf-help">실측 연결 · {node.psu_slot}<br/>서버 #{node.server_id}</p>{/if}
 <section class="pf-property-section"><h3>전력</h3><div class="pf-reading-grid"><div><span>현재</span><strong>{current(metric,'watts')}</strong><b>{current(metric,'amps')}</b></div><div><span>기간 최대 kW</span><strong>{peaksLoading&&metric?.peak_watts==null?'… kW':format(metric?.peak_watts,'kW')}</strong><small>{time(metric?.peak_watts_at)}</small></div><div><span>기간 최대 A</span><strong>{metric?.peak_amps==null?(peaksLoading?'… A':'—'):`≈ ${format(metric.peak_amps,'A')}`}</strong><small>{time(metric?.peak_amps_at)}</small></div></div>{#if peaksError}<p class="pf-help pf-status-overload">기간 최대 조회 실패 <button onclick={onretrypeaks}>다시 시도</button></p>{/if}<p class="pf-help">관측 {time(metric?.observed_at)}{#if metric&&!metric.complete}<br/>일부 전력원이 없거나 오래되었습니다.{/if}</p></section>
 {#if displayMode==='peak'&&node?.kind!=='server'}
 <section class="pf-property-section"><h3>관측 최대 기준 여유</h3><div class="pf-reading-grid"><div><span>정격 − 최대 kW</span><strong class:pf-status-overload={remaining.watts!==null&&remaining.watts<0}>{format(remaining.watts,'kW')}</strong></div><div><span>정격 − 최대 A</span><strong class:pf-status-overload={remaining.amps!==null&&remaining.amps<0}>{remaining.amps===null?'—':`${peakMetric?.amps_estimated?'≈ ':''}${format(remaining.amps,'A')}`}</strong></div></div></section>
 {/if}
 {#if node?.kind!=='server'}<section class="pf-property-section"><h3>{edge?'케이블 허용 용량':'정격 용량'}</h3><div class="pf-fields-row"><label class="pf-field">정격 A<input type="number" min="0.01" step="any" placeholder="미입력" disabled={!editable} value={capacity??''} onchange={event=>node?patchNode({capacity_a:number(event)}):patchEdge({capacity_a:number(event)})}/></label><label class="pf-field">경고 A<input type="number" min="0.01" step="any" placeholder="미입력" disabled={!editable} value={(node?.warning_a??edge?.warning_a)??''} onchange={event=>node?patchNode({warning_a:number(event)}):patchEdge({warning_a:number(event)})}/></label></div><p class="pf-help">환산 {capacity===null?'—':`≈ ${format(metric?.capacity_watts??capacity*voltage*pf,'kW')}`} · {voltage} V · PF {pf}</p>{#if metric?.utilization!=null}<p class="pf-utilization">현재 {metric.amps_estimated?'추정 부하율':'부하율'} <strong>{(metric.utilization*100).toLocaleString('ko-KR',{maximumFractionDigits:1})}%</strong>{#if metric.status==='overload'}<span class="pf-status-overload">{metric.amps_estimated?'추정 초과':'초과'}</span>{:else if metric.status==='warning'}<span class="pf-status-warning">{metric.amps_estimated?'추정 경고':'경고'}</span>{:else if metric.status==='estimated'}<span class="pf-status-estimated">전류 추정</span>{/if}</p>{/if}</section>
 {/if}
 {#if node&&node.kind!=='server'}
 <section class="pf-property-section"><h3>전기 조건</h3>{#if node.kind==='fixed'}<label class="pf-field">고정 소비 kW<input type="number" min="0" step="any" disabled={!editable} value={kilowatts(node.fixed_watts)??''} onchange={event=>patchNode({fixed_watts:wattsFromKilowatts(number(event))})}/></label>{/if}<div class="pf-fields-row"><label class="pf-field">전압 V<input type="number" min="1" step="any" placeholder={`${graph.settings.voltage_v} 상속`} disabled={!editable||node.kind!=='breaker'} value={node.kind==='breaker'?(node.voltage_v??''):voltage} onchange={event=>patchNode({voltage_v:number(event)})}/></label><label class="pf-field">역률 PF<input type="number" min="0.01" max="1" step="0.01" placeholder={`${graph.settings.power_factor} 상속`} disabled={!editable||!['psu','fixed'].includes(node.kind)} value={['psu','fixed'].includes(node.kind)?(node.power_factor??''):pf} onchange={event=>patchNode({power_factor:number(event)})}/></label></div></section>
 {#if ['breaker','outlet','strip'].includes(node.kind)}<section class="pf-property-section"><h3>포트</h3><label class="pf-field">출력 수<input type="number" min="1" max="24" disabled={!editable} value={node.ports.filter(p=>p.direction==='output').length} onchange={event=>onchange(patchOutputPorts(graph,node.id,Number(event.currentTarget.value)))}/></label>{#each node.ports as port}{@const portMetric=state?.ports[`${node.id}:${port.id}`]}<label class="pf-port-field"><span>{port.label}</span><input aria-label={`${port.label} 정격 A`} type="number" min="0.01" step="any" placeholder="정격 A" disabled={!editable} value={port.capacity_a??''} onchange={event=>patchNode({ports:node.ports.map(p=>p.id===port.id?{...p,capacity_a:number(event)}:p)})}/><span class="pf-port-metrics"><span>{current(portMetric,'watts')} · {current(portMetric,'amps')}</span>{#if portMetric?.status==='overload'}<strong class="pf-status-overload">{portMetric.amps_estimated?'추정 초과':'초과'}</strong>{:else if portMetric?.status==='warning'}<strong class="pf-status-warning">{portMetric.amps_estimated?'추정 경고':'경고'}</strong>{:else if portMetric?.status==='estimated'}<strong class="pf-status-estimated">전류 추정</strong>{:else if portMetric?.status==='unconnected'}<strong>미연결</strong>{:else if !portMetric||portMetric.status==='unknown'}<strong>미확인</strong>{/if}</span></label>{/each}</section>{/if}
 {/if}
 {#if editable}<button class="pf-button pf-delete" onclick={ondelete}>{node?.kind==='server'?'서버와 PSU 삭제':'선택 삭제'}</button>{/if}
 {:else}
 <section class="pf-property-section"><h3>전기 조건 · 사용자 설정</h3><p class="pf-help">초기값은 220 V · PF 1입니다. 현장 조건에 맞게 입력하세요. A는 추정값입니다.</p><div class="pf-fields-row"><label class="pf-field">전압 V<input type="number" min="1" step="any" disabled={!editable} value={graph.settings.voltage_v} onchange={event=>setting('voltage_v',event)}/></label><label class="pf-field">역률 PF<input type="number" min="0.01" max="1" step="0.01" disabled={!editable} value={graph.settings.power_factor} onchange={event=>setting('power_factor',event)}/></label></div></section>
 <section class="pf-property-section"><h3>측정 유효 범위</h3><label class="pf-field">최대 데이터 경과 (초)<input type="number" min="1" disabled={!editable} value={graph.settings.max_age_seconds} onchange={event=>setting('max_age_seconds',event)}/></label><label class="pf-field">측정 시각 허용 차이 (초)<input type="number" min="0" disabled={!editable} value={graph.settings.max_skew_seconds} onchange={event=>setting('max_skew_seconds',event)}/></label></section>
 <p class="pf-help">정격 A는 제품 표기와 배선 조건을 확인해 입력하세요. 미입력 용량은 판단하지 않습니다.</p>
 {/if}
</aside>
